
const KEY='creative_settings_app_v1',AUTO_KEY='creative_settings_app_auto_v6',DBNAME='creative_settings_images_v1';let db=load(),currentProjectId=null,limits={projects:20,settings:20,characters:20,relations:20,images:20,sources:20,stories:20,timeline:20};
function emptyDB(){return{projects:[],settings:[],stories:[],characters:[],relations:[],images:[],sources:[],timeline:[],trash:[],recentViews:[]}}
function normalize(d){d={...emptyDB(),...(d||{})};for(let k of Object.keys(emptyDB()))if(!Array.isArray(d[k]))d[k]=[];for(let p of d.projects)p.projectType=p.projectType||'general';for(let c of d.characters)c.musicTracks=c.musicTracks||[];return d}
function load(){try{return normalize(JSON.parse(localStorage.getItem(KEY)))}catch{return emptyDB()}}
function persist(){try{let prev=localStorage.getItem(KEY);if(prev)localStorage.setItem(AUTO_KEY,prev)}catch{}localStorage.setItem(KEY,JSON.stringify(db))}
function save(){persist();renderAll()}function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8)}function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function fmt(t){return new Date(t||Date.now()).toLocaleString('ko-KR')}function safeFileName(s='문서'){return s.replace(/[\\/:*?"<>|]/g,'_').trim()||'문서'}function v(id){return document.getElementById(id)?.value||''}function richText(id){return document.getElementById(id)?.innerText.replace(/\u00a0/g,' ')||''}function sanitizeRich(html=''){let t=document.createElement('template');t.innerHTML=html;let allowed=new Set(['B','STRONG','U','BR','DIV','P','FONT']);function clean(n){for(let c of[...n.childNodes]){if(c.nodeType===3)continue;if(c.nodeType!==1){c.remove();continue}if(!allowed.has(c.tagName)){c.replaceWith(document.createTextNode(c.textContent||''));continue}for(let a of[...c.attributes]){if(c.tagName==='FONT'&&a.name==='size'){let z=parseInt(a.value);if(z>=1&&z<=7)continue}c.removeAttribute(a.name)}clean(c)}}clean(t.content);return t.innerHTML}function richHtml(id){return sanitizeRich(document.getElementById(id)?.innerHTML||'')}function richInitial(x){return x?.bodyHtml?sanitizeRich(x.bodyHtml):esc(x?.body||'').replace(/\n/g,'<br>')}function richEditor(id,x){return `<div class="richWrap"><div class="richToolbar"><button type="button" title="굵게" onclick="richCmd('${id}','bold')"><b>B</b></button><button type="button" title="밑줄" onclick="richCmd('${id}','underline')"><u>U</u></button><select title="글자 크기" onchange="richSize('${id}',this.value);this.value=''"><option value="">글자 크기</option><option value="2">작게</option><option value="3">보통</option><option value="4">크게</option><option value="5">아주 크게</option></select><button type="button" onclick="richCmd('${id}','removeFormat')">서식 지우기</button></div><div id="${id}" class="richEditor" contenteditable="true">${richInitial(x)}</div></div>`}function richCmd(id,cmd){let e=document.getElementById(id);if(!e)return;e.focus();document.execCommand(cmd,false,null)}function richSize(id,size){if(!size)return;let e=document.getElementById(id);if(!e)return;e.focus();document.execCommand('fontSize',false,size)}function encodeObj(o){return `'${btoa(unescape(encodeURIComponent(JSON.stringify(o))))}'`}function decodeObj(s){return JSON.parse(decodeURIComponent(escape(atob(s))))}function resetLimit(k){limits[k]=20}function more(k,fn){limits[k]+=20;fn()}function currentTheme(){return db.projects.find(p=>p.id===currentProjectId)?.color||'#7b61a8'}function contrast(hex){let h=(hex||'#7b61a8').replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');let r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);return(r*299+g*587+b*114)/1000>160?'#222':'#fff'}function applyTheme(c='#7b61a8'){document.documentElement.style.setProperty('--theme',c);document.documentElement.style.setProperty('--themeInk',contrast(c));let dark=document.documentElement.dataset.mode==='dark';document.documentElement.style.setProperty('--soft',dark?`color-mix(in srgb, ${c} 16%, #292830)`:`color-mix(in srgb, ${c} 13%, white)`)}function setMode(mode){document.documentElement.dataset.mode=mode;localStorage.setItem('creativeStudioMode',mode);let b=document.getElementById('modeToggle');if(b)b.textContent=mode==='dark'?'☀️ 라이트':'🌙 다크';applyTheme(currentProjectId?currentTheme():'#5d5870');try{if(window.Android)Android.setSystemBars(mode==='dark')}catch(e){}}function toggleMode(){setMode(document.documentElement.dataset.mode==='dark'?'light':'dark')}function cap(s){return s[0].toUpperCase()+s.slice(1)}
function idb(){return new Promise((res,rej)=>{let r=indexedDB.open(DBNAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('files'))r.result.createObjectStore('files',{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}async function putFile(id,data){let d=await idb();return new Promise((res,rej)=>{let tx=d.transaction('files','readwrite');tx.objectStore('files').put({id,data});tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}async function getFile(id){let d=await idb();return new Promise((res,rej)=>{let r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result?.data||'');r.onerror=()=>rej(r.error)})}async function delFile(id){let d=await idb();return new Promise(res=>{let tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=res;tx.onerror=res})}async function clearFiles(){let d=await idb();return new Promise(res=>{let tx=d.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=res;tx.onerror=res})}function fileToData(f){return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
for(let b of document.querySelectorAll('.tabs button'))b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.tabsec').forEach(s=>s.classList.add('hidden'));document.getElementById(b.dataset.tab).classList.remove('hidden');if(b.dataset.tab==='export')renderExportProjects();if(b.dataset.tab==='trash')renderTrash()};for(let b of document.querySelectorAll('.subtabs button'))b.onclick=()=>{document.querySelectorAll('.subtabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.subsec').forEach(s=>s.classList.add('hidden'));document.getElementById('project'+cap(b.dataset.subtab)).classList.remove('hidden');if(b.dataset.subtab==='recent')renderRecent()};function openModal(h){document.getElementById('modalCard').innerHTML=h;document.getElementById('modal').classList.remove('hidden')}function closeModal(){document.getElementById('modal').classList.add('hidden')}document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()}
function statusOpts(cur='아이디어'){return['아이디어','검토중','확정','보류','폐기'].map(x=>`<option ${cur===x?'selected':''}>${x}</option>`).join('')}function tags(t=''){return String(t).split(',').map(x=>x.trim()).filter(Boolean).map(x=>`<span class="tag">#${esc(x)}</span>`).join('')}function sortArr(arr,mode){let a=[...arr];a.sort((x,y)=>Number(!!y.favorite)-Number(!!x.favorite));let fav=a.filter(x=>x.favorite),rest=a.filter(x=>!x.favorite);let s=z=>{if(mode==='oldest')z.sort((x,y)=>(x.updated||x.created||0)-(y.updated||y.created||0));else if(mode==='name')z.sort((x,y)=>(x.name||x.title||'').localeCompare(y.name||y.title||'','ko'));else z.sort((x,y)=>(y.updated||y.created||0)-(x.updated||x.created||0));return z};return[...s(fav),...s(rest)]}function toggleMore(id,total,limit){document.getElementById(id)?.classList.toggle('hidden',total<=limit)}function cnt(k,pid){return(db[k]||[]).filter(x=>x.project===pid).length}
function newProject(p){if(typeof p==='string')p=decodeObj(p);p=p||{id:uid(),name:'',desc:'',color:'#7b61a8',projectType:'general',created:Date.now(),updated:Date.now()};openModal(`<div class="stack"><h2>${p.name?'프로젝트 수정':'새 프로젝트'}</h2><input id="pname" placeholder="프로젝트 이름" value="${esc(p.name)}"><select id="ptype"><option value="general" ${(p.projectType||'general')==='general'?'selected':''}>일반 프로젝트 — 전체 기능</option><option value="short" ${p.projectType==='short'?'selected':''}>단편 프로젝트 — 단순화된 기능</option></select><div class="note">단편 프로젝트에서는 관계도와 타임라인을 숨기고 설정, 캐릭터, 이미지, 소스파일, 썰 중심으로 표시합니다. 이후 일반 프로젝트로 변경해도 기존 자료는 유지됩니다.</div><textarea id="pdesc" style="min-height:110px" placeholder="설명">${esc(p.desc||'')}</textarea><input id="pcolor" type="color" value="${esc(p.color||'#7b61a8')}"><div class="right">${p.name?`<button class="danger" onclick="trashProject('${p.id}')">삭제</button>`:''}<button onclick="closeModal()">취소</button><button class="primary" onclick="saveProject('${p.id}')">저장</button></div></div>`)}function saveProject(id){let name=v('pname').trim();if(!name)return alert('프로젝트 이름을 입력해 주세요.');let old=db.projects.find(x=>x.id===id);upsert('projects',{...old,id,name,desc:v('pdesc'),color:v('pcolor'),projectType:v('ptype')||'general',created:old?.created||Date.now(),updated:Date.now()});closeModal();if(currentProjectId===id)openProject(id)}function renderProjects(){let q=v('projectSearch').toLowerCase(),mode=v('projectSort')||'latest',arr=sortArr(db.projects.filter(p=>`${p.name} ${p.desc||''}`.toLowerCase().includes(q)),mode),shown=arr.slice(0,limits.projects);document.getElementById('projectList').innerHTML=shown.length?shown.map(p=>`<div class="card projectCard" style="--pcolor:${p.color||'#7b61a8'}" onclick="openProject('${p.id}')"><h3>${esc(p.name)}</h3><span class="typeBadge">${p.projectType==='short'?'단편 프로젝트':'일반 프로젝트'}</span><div class="meta">${fmt(p.updated||p.created)}</div><div class="snippet">${esc(p.desc||'설명 없음')}</div><div class="meta" style="margin-top:7px">설정 ${cnt('settings',p.id)} · 캐릭터 ${cnt('characters',p.id)} · 썰 ${cnt('stories',p.id)}${p.projectType==='short'?'':` · 관계도 ${cnt('relations',p.id)} · 타임라인 ${cnt('timeline',p.id)}`}</div><div class="right" style="margin-top:7px"><button onclick="event.stopPropagation();newProject(${encodeObj(p)})">수정</button><button class="danger" onclick="event.stopPropagation();trashProject('${p.id}')">삭제</button></div></div>`).join(''):'<div class="empty">새 프로젝트를 만들어 보세요.</div>';toggleMore('projectMore',arr.length,limits.projects)}function applyProjectType(p){let short=p.projectType==='short';for(let key of ['relations','timeline']){let btn=document.querySelector(`[data-subtab="${key}"]`),sec=document.getElementById('project'+(key==='relations'?'Relations':'Timeline'));if(btn)btn.classList.toggle('hidden',short);if(sec&&short)sec.classList.add('hidden')}let active=document.querySelector('.subtabs button.active');if(short&&active&&['relations','timeline'].includes(active.dataset.subtab)){document.querySelector('[data-subtab="recent"]').click()}}function openProject(id){let p=db.projects.find(x=>x.id===id);if(!p)return;currentProjectId=id;applyTheme(p.color);document.getElementById('projectHome').classList.add('hidden');document.getElementById('projectView').classList.remove('hidden');document.getElementById('projectCrumb').textContent=p.name;document.getElementById('projectTitle').textContent=p.name;document.getElementById('projectDesc').innerHTML=`<span class="typeBadge">${p.projectType==='short'?'단편 프로젝트':'일반 프로젝트'}</span> ${esc(p.desc||'설명 없음')}`;applyProjectType(p);for(let k of Object.keys(limits))if(k!=='projects')resetLimit(k);renderProjectAll();renderRecent()}function closeProject(){currentProjectId=null;applyTheme();document.getElementById('projectView').classList.add('hidden');document.getElementById('projectHome').classList.remove('hidden');renderProjects()}
function controls(kind,label,newFn,ph){return`<div class="toolbar"><div><h3 style="margin:0 0 4px">${label}</h3><div class="meta" id="${kind}Count"></div></div><button class="primary" onclick="${newFn}()">+ 새 항목</button></div><div class="toolbar"><input id="${kind}Search" class="search" placeholder="${ph}" oninput="resetLimit('${kind}');render${cap(kind)}()"><div class="right"><select id="${kind}Tag" class="filterSel" onchange="resetLimit('${kind}');render${cap(kind)}()"><option value="">모든 태그</option></select><select id="${kind}Sort" class="sorter" onchange="resetLimit('${kind}');render${cap(kind)}()"><option value="latest">최신순</option><option value="oldest">오래된 순</option><option value="name">이름순</option></select></div></div><div id="${kind}List" class="stack"></div><button id="${kind}More" class="loadMore hidden" onclick="more('${kind}',render${cap(kind)})">더 보기 +20</button>`}function setupSections(){projectSettings.innerHTML=controls('settings','설정 문서','newSetting','제목/태그/본문 검색...');projectCharacters.innerHTML=controls('characters','캐릭터','newCharacter','이름/설정 검색...');projectRelations.innerHTML=controls('relations','관계도 / 조직도','newRelation','관계 검색...');projectImages.innerHTML=controls('images','이미지 자료','newImage','이미지 검색...');projectSources.innerHTML=controls('sources','소스파일','newSource','PDF 검색...');projectStories.innerHTML=controls('stories','썰 / 장문','newStory','제목/본문 검색...');projectTimeline.innerHTML=controls('timeline','타임라인','newTimeline','사건/날짜/본문 검색...')}function listData(kind,fields){let all=db[kind].filter(x=>x.project===currentProjectId),tagSet=[...new Set(all.flatMap(x=>String(x.tags||'').split(',').map(t=>t.trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'ko')),tagSel=document.getElementById(kind+'Tag');if(tagSel){let old=tagSel.value;tagSel.innerHTML='<option value="">모든 태그</option>'+tagSet.map(t=>`<option value="${esc(t)}">#${esc(t)}</option>`).join('');if(tagSet.includes(old))tagSel.value=old}let q=v(kind+'Search').toLowerCase(),tg=v(kind+'Tag'),mode=v(kind+'Sort')||'latest',arr=all.filter(x=>fields.map(f=>x[f]||'').join(' ').toLowerCase().includes(q)&&(!tg||String(x.tags||'').split(',').map(t=>t.trim()).includes(tg)));arr=sortArr(arr,mode);document.getElementById(kind+'Count').textContent=`이 프로젝트에 ${all.length}개`;toggleMore(kind+'More',arr.length,limits[kind]);return arr.slice(0,limits[kind])}
function trackView(kind,id){if(!id)return;db.recentViews=db.recentViews.filter(x=>!(x.kind===kind&&x.id===id));db.recentViews.unshift({kind,id,project:currentProjectId,viewed:Date.now()});db.recentViews=db.recentViews.slice(0,80);persist()}function kindLabel(k){return{settings:'설정',characters:'캐릭터',relations:'관계도',images:'이미지',sources:'소스파일',stories:'썰',timeline:'타임라인'}[k]||k}function titleOf(k,x){return x?.name||x?.title||'이름 없음'}function getDoc(k,id){return(db[k]||[]).find(x=>x.id===id)}function openDoc(k,id){let x=getDoc(k,id);if(!x)return alert('연결된 문서를 찾을 수 없습니다.');currentProjectId=x.project;({settings:newSetting,characters:newCharacter,relations:newRelation,images:newImage,sources:newSource,stories:newStory,timeline:newTimeline}[k])(x)}function renderRecent(){let rv=db.recentViews.filter(x=>x.project===currentProjectId).slice(0,12),recent=rv.map(r=>{let x=getDoc(r.kind,r.id);return x?`<div class="item" onclick="openDoc('${r.kind}','${r.id}')"><b>${esc(titleOf(r.kind,x))}</b><div class="meta">${kindLabel(r.kind)} · ${fmt(r.viewed)}</div></div>`:''}).filter(Boolean).join('');let fav=[];for(let k of ['settings','characters','relations','images','sources','stories','timeline'])for(let x of db[k].filter(x=>x.project===currentProjectId&&x.favorite))fav.push({k,x});fav.sort((a,b)=>(b.x.updated||0)-(a.x.updated||0));let modified=[];for(let k of ['settings','characters','relations','images','sources','stories','timeline'])for(let x of db[k].filter(x=>x.project===currentProjectId))modified.push({k,x});modified.sort((a,b)=>(b.x.updated||0)-(a.x.updated||0));projectRecent.innerHTML=`<div class="toolbar"><h3>⭐ 즐겨찾기</h3></div><div class="recentGrid">${fav.length?fav.slice(0,12).map(o=>`<div class="item" onclick="openDoc('${o.k}','${o.x.id}')"><b>${esc(titleOf(o.k,o.x))}</b><div class="meta">${kindLabel(o.k)} · ${esc(o.x.status||'')}</div></div>`).join(''):'<div class="empty">즐겨찾기한 문서가 없습니다.</div>'}</div><div class="toolbar" style="margin-top:16px"><h3>✏️ 최근 수정한 문서</h3></div><div class="recentGrid">${modified.length?modified.slice(0,12).map(o=>`<div class="item" onclick="openDoc('${o.k}','${o.x.id}')"><b>${esc(titleOf(o.k,o.x))}</b><div class="meta">${kindLabel(o.k)} · ${fmt(o.x.updated)}</div></div>`).join(''):'<div class="empty">아직 수정한 문서가 없습니다.</div>'}</div><div class="toolbar" style="margin-top:16px"><h3>🕘 최근 본 문서</h3></div><div class="recentGrid">${recent||'<div class="empty">아직 열어본 문서가 없습니다.</div>'}</div>`}
function favButton(kind,x){return`<button class="favBtn" onclick="event.stopPropagation();toggleFav('${kind}','${x.id}')">${x.favorite?'★':'☆'}</button>`}function toggleFav(k,id){let x=getDoc(k,id);if(!x)return;x.favorite=!x.favorite;x.updated=Date.now();save()}
function linkedPicker(cur=[],selfKind='',selfId=''){let docs=[];for(let k of ['settings','characters','relations','stories','timeline'])for(let x of db[k].filter(x=>x.project===currentProjectId&&!(k===selfKind&&x.id===selfId)))docs.push({k,x});return`<div class="linkedBox"><b>문서 링크</b><div class="meta">관련 문서를 연결하면 아래에 바로가기 형태로 표시됩니다.</div><div style="max-height:180px;overflow:auto">${docs.length?docs.map(o=>`<label class="checkRow"><input type="checkbox" name="linkedDoc" value="${o.k}:${o.x.id}" ${cur.includes(o.k+':'+o.x.id)?'checked':''}> ${kindLabel(o.k)} · ${esc(titleOf(o.k,o.x))}</label>`).join(''):'<div class="meta">연결할 수 있는 문서가 아직 없습니다.</div>'}</div></div>`}function linkedValues(){return[...document.querySelectorAll('input[name=linkedDoc]:checked')].map(x=>x.value)}function linkedChips(ids=[]){return ids.map(s=>{let[k,id]=s.split(':'),x=getDoc(k,id);return x?`<button class="linkChip" onclick="event.stopPropagation();openDoc('${k}','${id}')">${kindLabel(k)} · ${esc(titleOf(k,x))}</button>`:''}).join('')}
function commonFields(x){return`<div class="row"><select id="xstatus">${statusOpts(x.status||'아이디어')}</select><label class="checkRow"><input id="xfav" type="checkbox" ${x.favorite?'checked':''}> 즐겨찾기</label></div>`}function commonData(x){return{status:v('xstatus')||x.status||'아이디어',favorite:!!document.getElementById('xfav')?.checked,linkedIds:linkedValues()}}
function newSetting(s){if(typeof s==='string')s=decodeObj(s);s=s||{id:uid(),title:'',type:'세계관',tags:'',body:'',status:'아이디어',favorite:false,linkedIds:[],project:currentProjectId};if(s.title)trackView('settings',s.id);let opts=['세계관','지역','조직','종족','아이템','연표','기타'].map(x=>`<option ${s.type===x?'selected':''}>${x}</option>`).join('');openModal(`<div class="stack"><h2>설정 문서</h2><div class="row"><input id="stitle" placeholder="제목" value="${esc(s.title)}"><select id="stype">${opts}</select></div>${commonFields(s)}<input id="stags" placeholder="태그" value="${esc(s.tags||'')}">${richEditor('sbody',s)}${linkedPicker(s.linkedIds||[],'settings',s.id)}<div class="right">${s.title?`<button onclick="exportItem('settings','${s.id}','txt')">TXT</button><button onclick="exportItem('settings','${s.id}','pdf')">PDF</button><button class="danger" onclick="trashItem('settings','${s.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveSetting('${s.id}')">저장</button></div></div>`)}function saveSetting(id){let title=v('stitle').trim();if(!title)return alert('제목을 입력해 주세요.');let old=getDoc('settings',id)||{};upsert('settings',{...old,id,title,type:v('stype'),tags:v('stags'),body:richText('sbody'),bodyHtml:richHtml('sbody'),project:currentProjectId,updated:Date.now(),...commonData(old)});closeModal()}function renderSettings(){let a=listData('settings',['title','type','tags','body','status']),el=settingsList;el.innerHTML=a.length?a.map(x=>`<div class="item ${x.favorite?'favorite':''}" onclick="newSetting(${encodeObj(x)})"><div class="right">${favButton('settings',x)}</div><b>${esc(x.title)}</b> <span class="status">${esc(x.status||'아이디어')}</span><div class="meta">${esc(x.type)} · ${fmt(x.updated)}</div>${tags(x.tags)}<div class="chips">${linkedChips(x.linkedIds)}</div><div class="snippet">${esc(x.body||'내용 없음')}</div></div>`).join(''):'<div class="empty">등록된 설정 문서가 없습니다.</div>'}
async function imagePickerOne(selected=''){let imgs=db.images.filter(x=>x.project===currentProjectId),out='<option value="">대표 이미지 없음</option>';for(let i of imgs)out+=`<option value="${i.id}" ${selected===i.id?'selected':''}>${esc(i.title)}</option>`;return out}
async function newCharacter(c){if(typeof c==='string')c=decodeObj(c);c=c||{id:uid(),name:'',alias:'',age:'',role:'',tags:'',body:'',relationIds:[],relationNotes:{},relationRanks:{},raceId:'',regionId:'',portraitId:'',musicTracks:[],status:'아이디어',favorite:false,linkedIds:[],project:currentProjectId};c.musicTracks=c.musicTracks||[];if(c.name)trackView('characters',c.id);let rels=db.relations.filter(r=>r.project===currentProjectId),checks=rels.map(r=>{let ck=(c.relationIds||[]).includes(r.id),ranks=r.kind==='소속'?(r.ranks||[]):[];return`<div class="relationLinkRow"><input type="checkbox" name="crel" value="${r.id}" ${ck?'checked':''} onchange="document.getElementById('rf_${r.id}').classList.toggle('hidden',!this.checked)"><div><b>${esc(r.title)}</b><div id="rf_${r.id}" class="stack ${ck?'':'hidden'}"><input id="rc_${r.id}" placeholder="관계 코멘트" value="${esc(c.relationNotes?.[r.id]||'')}">${r.kind==='소속'?`<select id="rr_${r.id}"><option value="">계급 미지정</option>${ranks.map(z=>`<option ${c.relationRanks?.[r.id]===z?'selected':''}>${esc(z)}</option>`).join('')}</select>`:''}</div></div></div>`}).join('');let races=db.settings.filter(s=>s.project===currentProjectId&&s.type==='종족'),regions=db.settings.filter(s=>s.project===currentProjectId&&s.type==='지역'),portraitOpts=await imagePickerOne(c.portraitId);let musicRows='';for(let m of c.musicTracks){let d=await getFile(m.id);musicRows+=musicRowHtml(m,d)}openModal(`<div class="stack"><h2>캐릭터</h2><div class="row"><input id="cname" placeholder="이름" value="${esc(c.name)}"><input id="calias" placeholder="별칭" value="${esc(c.alias||'')}"></div>${commonFields(c)}<div class="row3"><input id="cage" placeholder="나이" value="${esc(c.age||'')}"><input id="crole" placeholder="역할/직업" value="${esc(c.role||'')}"><select id="cportrait">${portraitOpts}</select></div><div class="row"><select id="crace"><option value="">종족 미지정</option>${races.map(s=>`<option value="${s.id}" ${c.raceId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><select id="cregion"><option value="">지역 미지정</option>${regions.map(s=>`<option value="${s.id}" ${c.regionId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><input id="ctags" placeholder="태그" value="${esc(c.tags||'')}">${richEditor('cbody',c)}<div class="linkedBox"><b>🎵 캐릭터송 / 음악</b><div class="note">MP3, M4A, OGG 등 브라우저가 지원하는 음악은 여기서 바로 재생할 수 있어. 재생이 안 되는 형식도 파일 저장은 가능해.</div><label class="btn" style="text-align:center">음악 파일 추가<input id="cmusicInput" type="file" accept="audio/*,.mp3,.m4a,.aac,.ogg,.wav,.flac" multiple hidden onchange="addCharacterMusic(event)"></label><div id="cmusicList" class="musicList">${musicRows||'<div class="meta" id="noMusic">등록된 음악이 없습니다.</div>'}</div></div><div class="linkedBox"><b>관계도 / 소속</b>${checks||'<div class="meta">등록된 관계도가 없습니다.</div>'}</div>${linkedPicker(c.linkedIds||[],'characters',c.id)}<div class="right">${c.name?`<button onclick="exportItem('characters','${c.id}','txt')">TXT</button><button onclick="exportItem('characters','${c.id}','pdf')">PDF</button><button class="danger" onclick="trashItem('characters','${c.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveCharacter('${c.id}')">저장</button></div></div>`);window._editingMusic=[...c.musicTracks]}function musicRowHtml(m,data){return`<div class="musicRow" data-music-id="${m.id}" data-music-name="${esc(m.name)}"><div><b>${esc(m.name)}</b>${data?`<audio controls preload="metadata" src="${data}"></audio>`:'<div class="meta">파일을 불러올 수 없습니다.</div>'}</div><div class="right"><button type="button" onclick="downloadMusic('${m.id}','${encodeURIComponent(m.name)}')">저장</button><button type="button" class="danger" onclick="removeCharacterMusic('${m.id}',this)">삭제</button></div></div>`}async function addCharacterMusic(e){let files=[...(e.target.files||[])];if(!files.length)return;document.getElementById('noMusic')?.remove();for(let f of files){let id='music_'+uid(),data=await fileToData(f),m={id,name:f.name,type:f.type||'',size:f.size||0};await putFile(id,data);window._editingMusic=window._editingMusic||[];window._editingMusic.push(m);document.getElementById('cmusicList').insertAdjacentHTML('beforeend',musicRowHtml(m,data))}e.target.value=''}async function removeCharacterMusic(id,btn){if(!confirm('이 음악을 캐릭터에서 제거하시겠습니까?'))return;await delFile(id);window._editingMusic=(window._editingMusic||[]).filter(m=>m.id!==id);btn.closest('.musicRow')?.remove();if(!document.querySelector('#cmusicList .musicRow'))document.getElementById('cmusicList').innerHTML='<div class="meta" id="noMusic">등록된 음악이 없습니다.</div>'}async function downloadMusic(id,name){let d=await getFile(id);if(!d)return alert('음악 파일을 찾을 수 없습니다.');let a=document.createElement('a');a.href=d;a.download=decodeURIComponent(name||'character-song');a.click()}function saveCharacter(id){let name=v('cname').trim();if(!name)return alert('이름을 입력해 주세요.');let relationIds=[...document.querySelectorAll('input[name=crel]:checked')].map(x=>x.value),relationNotes={},relationRanks={};for(let rid of relationIds){relationNotes[rid]=v('rc_'+rid);if(document.getElementById('rr_'+rid))relationRanks[rid]=v('rr_'+rid)}let old=getDoc('characters',id)||{};upsert('characters',{...old,id,name,alias:v('calias'),age:v('cage'),role:v('crole'),raceId:v('crace'),regionId:v('cregion'),portraitId:v('cportrait'),tags:v('ctags'),body:richText('cbody'),bodyHtml:richHtml('cbody'),musicTracks:window._editingMusic||old.musicTracks||[],relationIds,relationNotes,relationRanks,project:currentProjectId,updated:Date.now(),...commonData(old)});window._editingMusic=[];closeModal()}async function renderCharacters(){let a=listData('characters',['name','alias','role','tags','body','status']),blocks=[];for(let c of a){let portrait=c.portraitId?await getFile(c.portraitId):'',race=getDoc('settings',c.raceId)?.title,region=getDoc('settings',c.regionId)?.title,rels=(c.relationIds||[]).map(id=>{let r=getDoc('relations',id);return r?`${r.title}${c.relationRanks?.[id]?' · '+c.relationRanks[id]:''}`:''}).filter(Boolean),musicCount=(c.musicTracks||[]).length;blocks.push(`<div class="item ${c.favorite?'favorite':''}" onclick="newCharacter(${encodeObj(c)})">${portrait?`<img class="portrait" src="${portrait}">`:''}<div class="right">${favButton('characters',c)}</div><b>${esc(c.name)}</b> <span class="status">${esc(c.status||'아이디어')}</span><div class="meta">${esc(c.age||'나이 미정')} · ${esc(c.role||'역할 미정')} · ${fmt(c.updated)}</div><div class="chips">${race?`<span class="pill">종족 · ${esc(race)}</span>`:''}${region?`<span class="pill">지역 · ${esc(region)}</span>`:''}${musicCount?`<span class="pill">🎵 캐릭터송 ${musicCount}곡</span>`:''}</div>${tags(c.tags)}${rels.length?`<div class="meta">관계/소속: ${rels.map(esc).join(', ')}</div>`:''}<div class="chips">${linkedChips(c.linkedIds)}</div><div class="snippet">${esc(c.body||'설정 없음')}</div></div>`)}charactersList.innerHTML=blocks.length?blocks.join(''):'<div class="empty">등록된 캐릭터가 없습니다.</div>'}
function relationViz(r){
  if(!r)return '<div class="meta">미리보기가 없습니다.</div>';
  if(r.kind==='소속'){
    let ranks=Array.isArray(r.ranks)?r.ranks:[];
    if(!ranks.length)return '<div class="meta">계급을 추가하면 조직도 미리보기가 표시됩니다.</div>';
    let notes=Array.isArray(r.rankNotes)?r.rankNotes:[];return `<div class="stack" style="margin-top:10px">${ranks.map((rank,i)=>`<div class="linkedBox" style="text-align:center"><b>${esc(rank)}</b>${notes[i]?`<div class="meta" style="margin-top:5px">${esc(notes[i])}</div>`:''}${i<ranks.length-1?'<div class="meta" style="margin-top:6px">↓</div>':''}</div>`).join('')}</div>`;
  }
  let members=String(r.members||r.people||'').split(',').map(x=>x.trim()).filter(Boolean);
  if(!members.length)return '<div class="meta">대상을 입력하면 관계 미리보기가 표시됩니다.</div>';
  return `<div class="chips" style="margin-top:10px">${members.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div>`;
}
function newRelation(r){if(typeof r==='string')r=decodeObj(r);r=r||{id:uid(),title:'',kind:'혼합',members:'',ranks:[],body:'',tags:'',status:'아이디어',favorite:false,linkedIds:[],project:currentProjectId};if(r.title)trackView('relations',r.id);r.ranks=Array.isArray(r.ranks)?r.ranks:[];r.rankNotes=Array.isArray(r.rankNotes)?r.rankNotes:[];let rankInputs=(r.ranks.length?r.ranks:['']).map((x,i)=>`<div class="rankDetailRow"><input class="rankInput" value="${esc(x)}" placeholder="계급 이름"><input class="rankNote" value="${esc(r.rankNotes[i]||'')}" placeholder="계급 설명 / 코멘트"><button type="button" onclick="this.parentElement.remove()">삭제</button></div>`).join('');openModal(`<div class="stack"><h2>${r.kind==='소속'?'조직도':'관계도'}</h2><div class="row"><input id="rtitle" placeholder="제목" value="${esc(r.title)}"><select id="rkind" onchange="refreshRelationMode()"><option ${r.kind==='인물'?'selected':''}>인물</option><option ${r.kind==='소속'?'selected':''}>소속</option><option ${r.kind==='혼합'?'selected':''}>혼합</option></select></div>${commonFields(r)}<div id="normalRelationFields" class="${r.kind==='소속'?'hidden':''}"><input id="rmembers" placeholder="대상 (쉼표로 구분)" value="${esc(r.members||r.people||'')}"></div><div id="orgRelationFields" class="linkedBox ${r.kind==='소속'?'':'hidden'}"><b>계급 구조</b><div id="rankList" class="stack">${rankInputs}</div><button onclick="addRankRow()">+ 계급 추가</button></div><input id="rtags" placeholder="태그" value="${esc(r.tags||'')}">${richEditor('rbody',r)}<div class="card"><b>미리보기</b>${relationViz(r)}</div>${linkedPicker(r.linkedIds||[],'relations',r.id)}<div class="right">${r.title?`<button onclick="exportItem('relations','${r.id}','txt')">TXT</button><button onclick="exportItem('relations','${r.id}','pdf')">PDF</button><button class="danger" onclick="trashItem('relations','${r.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveRelation('${r.id}')">저장</button></div></div>`)}function refreshRelationMode(){let org=v('rkind')==='소속';normalRelationFields.classList.toggle('hidden',org);orgRelationFields.classList.toggle('hidden',!org)}function addRankRow(){rankList.insertAdjacentHTML('beforeend','<div class="rankDetailRow"><input class="rankInput" placeholder="계급 이름"><input class="rankNote" placeholder="계급 설명 / 코멘트"><button type="button" onclick="this.parentElement.remove()">삭제</button></div>')}function saveRelation(id){let title=v('rtitle').trim();if(!title)return alert('제목을 입력해 주세요.');let kind=v('rkind'),rows=[...document.querySelectorAll('.rankDetailRow')],ranks=[],rankNotes=[];for(let row of rows){let n=row.querySelector('.rankInput')?.value.trim()||'',note=row.querySelector('.rankNote')?.value.trim()||'';if(n){ranks.push(n);rankNotes.push(note)}}let old=getDoc('relations',id)||{};upsert('relations',{...old,id,title,kind,members:kind==='소속'?'':v('rmembers'),ranks,rankNotes,body:richText('rbody'),bodyHtml:richHtml('rbody'),tags:v('rtags'),project:currentProjectId,updated:Date.now(),...commonData(old)});closeModal()}function renderRelations(){let a=listData('relations',['title','members','people','tags','body','kind','status']);relationsList.innerHTML=a.length?a.map(r=>`<div class="item ${r.favorite?'favorite':''}" onclick="newRelation(${encodeObj(r)})"><div class="right">${favButton('relations',r)}</div><b>${esc(r.title)}</b> <span class="status">${esc(r.status||'아이디어')}</span><div class="meta">${r.kind==='소속'?`조직도 · ${(r.ranks||[]).map(esc).join(' > ')||'계급 미지정'}`:`${esc(r.kind||'혼합')} · ${esc(r.members||r.people||'대상 미지정')}`}</div>${tags(r.tags)}<div class="chips">${linkedChips(r.linkedIds)}</div><div class="snippet">${esc(r.body||'내용 없음')}</div></div>`).join(''):'<div class="empty">등록된 관계도가 없습니다.</div>'}
async function newImage(i){if(typeof i==='string')i=decodeObj(i);i=i||{id:uid(),title:'',tags:'',note:'',favorite:false,project:currentProjectId};if(i.title)trackView('images',i.id);let existing=i.title?await getFile(i.id):'';openModal(`<div class="stack"><h2>이미지</h2><input id="ititle" placeholder="제목" value="${esc(i.title)}"><label class="checkRow"><input id="ifav" type="checkbox" ${i.favorite?'checked':''}> 즐겨찾기</label><input id="itags" placeholder="태그" value="${esc(i.tags||'')}"><textarea id="inote" style="min-height:120px">${esc(i.note||'')}</textarea><label class="btn" style="text-align:center">이미지 선택<input id="ifile" type="file" accept="image/*" hidden></label><div id="imgPrev">${existing?`<img style="max-width:100%;max-height:420px" src="${existing}">`:''}</div><div class="right">${i.title?`<button onclick="downloadStoredFile('${i.id}','${esc(i.title)}.png')">원본 저장</button><button class="danger" onclick="trashItem('images','${i.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveImage('${i.id}')">저장</button></div></div>`);ifile.onchange=async e=>{let f=e.target.files?.[0];if(!f)return;let d=await fileToData(f);imgPrev.dataset.data=d;imgPrev.innerHTML=`<img style="max-width:100%;max-height:420px" src="${d}">`}}async function saveImage(id){let title=v('ititle').trim();if(!title)return alert('제목을 입력해 주세요.');let data=imgPrev.dataset.data,old=getDoc('images',id);if(data)await putFile(id,data);else if(!old)return alert('이미지를 선택해 주세요.');upsert('images',{...old,id,title,tags:v('itags'),note:v('inote'),favorite:!!ifav.checked,project:currentProjectId,updated:Date.now()});closeModal()}async function renderImages(){let a=listData('images',['title','tags','note']),blocks=[];for(let i of a){let d=await getFile(i.id);blocks.push(`<div class="item ${i.favorite?'favorite':''}" onclick="newImage(${encodeObj(i)})">${d?`<img style="width:100%;height:140px;object-fit:cover;border-radius:10px" src="${d}">`:''}<div class="right">${favButton('images',i)}</div><b>${esc(i.title)}</b>${tags(i.tags)}<div class="snippet">${esc(i.note||'메모 없음')}</div></div>`)}imagesList.className='gallery';imagesList.innerHTML=blocks.length?blocks.join(''):'<div class="empty">등록된 이미지가 없습니다.</div>'}
function nativePdfPreview(data,name){if(window.Android)return `<div class="nativePdfBox"><div class="meta">${esc(name||'PDF')}</div><div>앱에서는 PDF 원본 저장 후 기기의 PDF 앱에서 확인하실 수 있습니다.</div><button type="button" onclick="appSaveDataUrl('${data}','${esc(name||'document.pdf')}')">PDF 저장 / 열기</button></div>`;return `<div class="meta">${esc(name||'PDF')}</div><iframe class="pdfPreview" src="${data}"></iframe>`}
async function newSource(f){if(typeof f==='string')f=decodeObj(f);f=f||{id:uid(),title:'',tags:'',note:'',favorite:false,project:currentProjectId};if(f.title)trackView('sources',f.id);let existing=f.title?await getFile(f.id):'';openModal(`<div class="stack"><h2>소스파일 PDF</h2><input id="ftitle" placeholder="제목" value="${esc(f.title)}"><label class="checkRow"><input id="ffav" type="checkbox" ${f.favorite?'checked':''}> 즐겨찾기</label><input id="ftags" placeholder="태그" value="${esc(f.tags||'')}"><textarea id="fnote" style="min-height:120px">${esc(f.note||'')}</textarea><label class="btn" style="text-align:center">PDF 선택<input id="fpdf" type="file" accept="application/pdf,.pdf" hidden></label><div id="pdfArea">${existing?nativePdfPreview(existing,f.fileName||'PDF'):'<div class="empty">PDF를 선택하면 미리보기가 표시됩니다.</div>'}</div><div class="right">${f.title?`<button onclick="downloadStoredFile('${f.id}','${esc(f.fileName||f.title+'.pdf')}')">원본 PDF 저장</button><button class="danger" onclick="trashItem('sources','${f.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveSource('${f.id}')">저장</button></div></div>`);fpdf.onchange=async e=>{let file=e.target.files?.[0];if(!file)return;let data=await fileToData(file);pdfArea.dataset.data=data;pdfArea.dataset.name=file.name;pdfArea.innerHTML=nativePdfPreview(data,file.name)}}async function saveSource(id){let title=v('ftitle').trim();if(!title)return alert('제목을 입력해 주세요.');let old=getDoc('sources',id),data=pdfArea.dataset.data;if(data)await putFile(id,data);else if(!old)return alert('PDF를 선택해 주세요.');upsert('sources',{...old,id,title,tags:v('ftags'),note:v('fnote'),favorite:!!ffav.checked,fileName:pdfArea.dataset.name||old?.fileName||title+'.pdf',project:currentProjectId,updated:Date.now()});closeModal()}function renderSources(){let a=listData('sources',['title','tags','note','fileName']);sourcesList.innerHTML=a.length?a.map(f=>`<div class="item ${f.favorite?'favorite':''}" onclick="newSource(${encodeObj(f)})"><div class="right">${favButton('sources',f)}</div><div style="font-size:34px">📄</div><b>${esc(f.title)}</b><div class="meta">${esc(f.fileName||'PDF')} · ${fmt(f.updated)}</div>${tags(f.tags)}<div class="snippet">${esc(f.note||'메모 없음')}</div></div>`).join(''):'<div class="empty">등록된 PDF 소스파일이 없습니다.</div>'}async function downloadStoredFile(id,name){let d=await getFile(id);if(!d)return alert('파일을 찾을 수 없습니다.');appSaveDataUrl(d,name)}
async function newStory(s){if(typeof s==='string')s=decodeObj(s);s=s||{id:uid(),title:'',tags:'',body:'',imageIds:[],status:'아이디어',favorite:false,linkedIds:[],project:currentProjectId};if(s.title)trackView('stories',s.id);let picks=[];for(let i of db.images.filter(x=>x.project===currentProjectId)){let d=await getFile(i.id);picks.push(`<label><img src="${d}"><div><input type="checkbox" name="storyImg" value="${i.id}" ${(s.imageIds||[]).includes(i.id)?'checked':''}> ${esc(i.title)}</div></label>`)}openModal(`<div class="stack"><h2>썰 / 장문</h2><input id="ttitle" placeholder="제목" value="${esc(s.title)}">${commonFields(s)}<input id="ttags" placeholder="태그" value="${esc(s.tags||'')}">${richEditor('tbody',s)}<div class="meta"><span id="charCount">${(s.body||'').length.toLocaleString()}</span>자</div><div class="linkedBox"><b>이미지 삽입</b><div class="imagePick">${picks.join('')||'<div class="meta">등록된 이미지가 없습니다.</div>'}</div><label class="btn" style="text-align:center">+ 새 이미지<input id="storyFiles" type="file" accept="image/*" multiple hidden></label></div>${linkedPicker(s.linkedIds||[],'stories',s.id)}<div class="right">${s.title?`<button onclick="exportItem('stories','${s.id}','txt')">TXT</button><button onclick="exportItem('stories','${s.id}','pdf')">PDF</button><button class="danger" onclick="trashItem('stories','${s.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveStory('${s.id}')">저장</button></div></div>`);document.getElementById('tbody').classList.add('storyLongEditor');document.getElementById('tbody').oninput=e=>charCount.textContent=e.target.innerText.length.toLocaleString()}async function saveStory(id){let title=v('ttitle').trim();if(!title)return alert('제목을 입력해 주세요.');let imageIds=[...document.querySelectorAll('input[name=storyImg]:checked')].map(x=>x.value);for(let f of [...(storyFiles.files||[])]){let iid=uid(),data=await fileToData(f);await putFile(iid,data);db.images.unshift({id:iid,title:f.name.replace(/\.[^.]+$/,''),tags:'',note:'썰에서 추가',project:currentProjectId,updated:Date.now()});imageIds.push(iid)}let old=getDoc('stories',id)||{};upsert('stories',{...old,id,title,tags:v('ttags'),body:richText('tbody'),bodyHtml:richHtml('tbody'),imageIds,project:currentProjectId,updated:Date.now(),...commonData(old)});closeModal()}async function renderStories(){let a=listData('stories',['title','tags','body','status']),blocks=[];for(let s of a){let thumbs=[];for(let iid of(s.imageIds||[]).slice(0,4)){let d=await getFile(iid);if(d)thumbs.push(`<img class="storyThumb" src="${d}">`)}blocks.push(`<div class="item ${s.favorite?'favorite':''}" onclick="newStory(${encodeObj(s)})"><div class="right">${favButton('stories',s)}</div><b>${esc(s.title)}</b> <span class="status">${esc(s.status||'아이디어')}</span><div class="meta">${fmt(s.updated)} · ${(s.body||'').length.toLocaleString()}자</div>${tags(s.tags)}${thumbs.length?`<div class="thumbRow">${thumbs.join('')}</div>`:''}<div class="chips">${linkedChips(s.linkedIds)}</div><div class="snippet">${esc(s.body||'내용 없음')}</div></div>`)}storiesList.innerHTML=blocks.length?blocks.join(''):'<div class="empty">저장된 썰이 없습니다.</div>'}
function newTimeline(t){if(typeof t==='string')t=decodeObj(t);t=t||{id:uid(),title:'',dateLabel:'',order:'',tags:'',body:'',status:'아이디어',favorite:false,linkedIds:[],project:currentProjectId};if(t.title)trackView('timeline',t.id);openModal(`<div class="stack"><h2>타임라인 사건</h2><input id="lttitle" placeholder="사건 제목" value="${esc(t.title)}">${commonFields(t)}<div class="row"><input id="ltdate" placeholder="날짜/시기 (예: 왕력 203년 봄)" value="${esc(t.dateLabel||'')}"><input id="ltorder" type="number" placeholder="정렬 순서" value="${esc(t.order??'')}"></div><input id="lttags" placeholder="태그" value="${esc(t.tags||'')}">${richEditor('ltbody',t)}${linkedPicker(t.linkedIds||[],'timeline',t.id)}<div class="right">${t.title?`<button onclick="exportItem('timeline','${t.id}','txt')">TXT</button><button onclick="exportItem('timeline','${t.id}','pdf')">PDF</button><button class="danger" onclick="trashItem('timeline','${t.id}')">삭제</button>`:''}<button onclick="closeModal()">닫기</button><button class="primary" onclick="saveTimeline('${t.id}')">저장</button></div></div>`)}function saveTimeline(id){let title=v('lttitle').trim();if(!title)return alert('사건 제목을 입력해 주세요.');let old=getDoc('timeline',id)||{};upsert('timeline',{...old,id,title,dateLabel:v('ltdate'),order:v('ltorder'),tags:v('lttags'),body:richText('ltbody'),bodyHtml:richHtml('ltbody'),project:currentProjectId,updated:Date.now(),...commonData(old)});closeModal()}function renderTimeline(){let a=listData('timeline',['title','dateLabel','tags','body','status']);a=[...a].sort((x,y)=>{let ax=x.order===''||x.order==null?999999:Number(x.order),ay=y.order===''||y.order==null?999999:Number(y.order);return ax-ay||(x.updated||0)-(y.updated||0)});timelineList.innerHTML=a.length?`<div class="timelineLine">${a.map(t=>`<div class="item timelineItem ${t.favorite?'favorite':''}" onclick="newTimeline(${encodeObj(t)})"><div class="right">${favButton('timeline',t)}</div><b>${esc(t.title)}</b> <span class="status">${esc(t.status||'아이디어')}</span><div class="meta">${esc(t.dateLabel||'시기 미정')}${t.order!==''&&t.order!=null?' · 순서 '+esc(t.order):''}</div>${tags(t.tags)}<div class="chips">${linkedChips(t.linkedIds)}</div><div class="snippet">${esc(t.body||'내용 없음')}</div></div>`).join('')}</div>`:'<div class="empty">등록된 타임라인 사건이 없습니다.</div>'}
function upsert(kind,obj,rerender=true){let i=db[kind].findIndex(x=>x.id===obj.id);i>=0?db[kind][i]=obj:db[kind].unshift(obj);persist();if(rerender)renderAll()}function trashItem(kind,id){let x=getDoc(kind,id);if(!x||!confirm('휴지통으로 이동하시겠습니까?'))return;db.trash.unshift({id:uid(),kind,data:x,deletedAt:Date.now()});db[kind]=db[kind].filter(z=>z.id!==id);persist();closeModal();renderAll()}function trashProject(pid){let p=db.projects.find(x=>x.id===pid);if(!p||!confirm(`'${p.name}' 프로젝트 전체를 휴지통으로 이동하시겠습니까?`))return;let bundle={project:p,items:{}};for(let k of ['settings','characters','relations','images','sources','stories','timeline']){bundle.items[k]=db[k].filter(x=>x.project===pid);db[k]=db[k].filter(x=>x.project!==pid)}db.projects=db.projects.filter(x=>x.id!==pid);db.trash.unshift({id:uid(),kind:'project',data:bundle,deletedAt:Date.now()});currentProjectId=null;persist();closeModal();closeProject();renderAll()}function renderTrash(){trashList.innerHTML=db.trash.length?db.trash.map(t=>{let title=t.kind==='project'?t.data.project.name:titleOf(t.kind,t.data);return`<div class="card trashRow"><div><b>${esc(title)}</b><div class="meta">${kindLabel(t.kind)} · 삭제 ${fmt(t.deletedAt)}</div></div><div class="right"><button onclick="restoreTrash('${t.id}')">복원</button><button class="danger" onclick="purgeTrash('${t.id}')">영구삭제</button></div></div>`}).join(''):'<div class="empty">휴지통이 비어 있습니다.</div>'}function restoreTrash(id){let t=db.trash.find(x=>x.id===id);if(!t)return;if(t.kind==='project'){db.projects.push(t.data.project);for(let[k,arr]of Object.entries(t.data.items||{}))db[k].push(...arr)}else db[t.kind].push(t.data);db.trash=db.trash.filter(x=>x.id!==id);save();renderTrash()}async function purgeTrash(id){let t=db.trash.find(x=>x.id===id);if(!t)return;if(!confirm('영구 삭제하시겠습니까? 삭제 후에는 복원할 수 없습니다.'))return;let ids=[];if(t.kind==='images'||t.kind==='sources')ids=[t.data.id];if(t.kind==='characters')ids=(t.data.musicTracks||[]).map(m=>m.id);if(t.kind==='project'){ids=[...(t.data.items?.images||[]),...(t.data.items?.sources||[])].map(x=>x.id);for(let c of(t.data.items?.characters||[]))ids.push(...(c.musicTracks||[]).map(m=>m.id))}for(let fid of ids)await delFile(fid);db.trash=db.trash.filter(x=>x.id!==id);persist();renderTrash()}async function emptyTrash(){if(!db.trash.length||!confirm('휴지통의 모든 항목을 영구 삭제하시겠습니까?'))return;for(let t of [...db.trash]){let ids=t.kind==='project'?[...(t.data.items?.images||[]),...(t.data.items?.sources||[])].map(x=>x.id):(t.kind==='images'||t.kind==='sources'?[t.data.id]:(t.kind==='characters'?(t.data.musicTracks||[]).map(m=>m.id):[]));if(t.kind==='project')for(let c of(t.data.items?.characters||[]))ids.push(...(c.musicTracks||[]).map(m=>m.id));for(let id of ids)await delFile(id)}db.trash=[];persist();renderTrash()}
function itemText(kind,x){if(kind==='settings')return`${x.title}\n분류: ${x.type}\n상태: ${x.status||''}\n태그: ${x.tags||''}\n\n${x.body||''}`;if(kind==='characters'){let race=getDoc('settings',x.raceId)?.title||'',region=getDoc('settings',x.regionId)?.title||'',rel=(x.relationIds||[]).map(id=>{let r=getDoc('relations',id);return r?`${r.title}${x.relationRanks?.[id]?' ['+x.relationRanks[id]+']':''}${x.relationNotes?.[id]?' — '+x.relationNotes[id]:''}`:''}).filter(Boolean).join('\n');return`${x.name}${x.alias?' / '+x.alias:''}\n상태: ${x.status||''}\n나이: ${x.age||''}\n역할: ${x.role||''}\n종족: ${race}\n지역: ${region}\n태그: ${x.tags||''}\n캐릭터송: ${(x.musicTracks||[]).map(m=>m.name).join(', ')||'없음'}\n관계/소속:\n${rel||'없음'}\n\n${x.body||''}`};if(kind==='relations')return`${x.title}\n유형: ${x.kind==='소속'?'조직도':x.kind}\n상태: ${x.status||''}\n${x.kind==='소속'?'계급: '+(x.ranks||[]).map((r,i)=>r+(x.rankNotes?.[i]?' — '+x.rankNotes[i]:'')).join(' > '):'대상: '+(x.members||x.people||'')}\n태그: ${x.tags||''}\n\n${x.body||''}`;if(kind==='stories')return`${x.title}\n상태: ${x.status||''}\n태그: ${x.tags||''}\n\n${x.body||''}`;if(kind==='timeline')return`${x.title}\n시기: ${x.dateLabel||''}\n순서: ${x.order||''}\n상태: ${x.status||''}\n태그: ${x.tags||''}\n\n${x.body||''}`;return''}async function exportItem(kind,id,format){let x=getDoc(kind,id);if(!x)return;let title=titleOf(kind,x),txt=itemText(kind,x);if(format==='txt'){return appSaveBlob(new Blob(['\ufeff'+txt],{type:'text/plain;charset=utf-8'}),title+'.txt')}let extra='';if(kind==='stories')for(let iid of(x.imageIds||[])){let d=await getFile(iid);if(d)extra+=`<img src="${d}">`}if(kind==='characters'&&x.portraitId){let d=await getFile(x.portraitId);if(d)extra=`<img src="${d}">`+extra}let html=`<h1>${esc(title)}</h1><div>${esc(txt).replace(/\n/g,'<br>')}</div>${extra}`;if(appPrint(title,html))return;let w=window.open('','_blank');if(!w)return alert('팝업을 허용해 주세요.');w.document.write(`<!doctype html><meta charset="utf-8"><style>body{font-family:system-ui;max-width:800px;margin:36px auto;padding:0 22px;line-height:1.7}img{max-width:100%;max-height:500px;object-fit:contain;margin:14px 0}</style>${html}<script>setTimeout(()=>print(),500)<\/script>`);w.document.close()}
function renderExportProjects(){exportProject.innerHTML=db.projects.length?db.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(''):'<option value="">프로젝트가 없습니다</option>'}function buildTxt(pid){let p=db.projects.find(x=>x.id===pid);if(!p)return'';let out=`${p.name}\n${'='.repeat(Math.max(4,p.name.length))}\n\n${p.desc||''}\n\n`;for(let[k,label]of[['settings','설정'],['characters','캐릭터'],['relations','관계도'],['stories','썰 / 장문'],['timeline','타임라인']]){let arr=db[k].filter(x=>x.project===pid);out+=`[${label} ${arr.length}개]\n\n`;arr.forEach((x,i)=>out+=`${i+1}. ${itemText(k,x)}\n\n`)}let imgs=db.images.filter(x=>x.project===pid),src=db.sources.filter(x=>x.project===pid);out+=`[이미지 ${imgs.length}개]\n${imgs.map(x=>'- '+x.title).join('\n')}\n\n[소스파일 ${src.length}개]\n${src.map(x=>'- '+x.title+' / '+(x.fileName||'PDF')).join('\n')}\n`;return out}function exportTxt(){let pid=v('exportProject'),p=db.projects.find(x=>x.id===pid);if(!p)return alert('프로젝트가 없습니다.');appSaveBlob(new Blob(['\ufeff'+buildTxt(pid)],{type:'text/plain;charset=utf-8'}),p.name+'.txt')}
async function exportPdf(){let pid=v('exportProject'),p=db.projects.find(x=>x.id===pid);if(!p)return alert('프로젝트가 없습니다.');let html=`<h1>${esc(p.name)}</h1><p>${esc(p.desc||'')}</p><pre>${esc(buildTxt(pid))}</pre>`;for(let i of db.images.filter(x=>x.project===pid)){let d=await getFile(i.id);if(d)html+=`<h3>${esc(i.title)}</h3><img src="${d}">`}if(appPrint(p.name,html))return;let w=window.open('','_blank');if(!w)return alert('팝업을 허용해 주세요.');w.document.write(`<!doctype html><meta charset="utf-8"><style>body{font-family:system-ui;max-width:800px;margin:30px auto;padding:0 22px;line-height:1.6}img{max-width:100%;max-height:500px;object-fit:contain}pre{white-space:pre-wrap;font-family:inherit}</style>${html}<script>setTimeout(()=>print(),600)<\/script>`);w.document.close()}
async function exportData(){let b=JSON.parse(JSON.stringify(db));b._fileData={};for(let x of[...db.images,...db.sources]){let d=await getFile(x.id);if(d)b._fileData[x.id]=d}for(let c of db.characters)for(let m of(c.musicTracks||[])){let d=await getFile(m.id);if(d)b._fileData[m.id]=d}appSaveBlob(new Blob([JSON.stringify(b)],{type:'application/json'}),'창작소_백업.json')}
function importData(e){let f=e.target.files?.[0];if(!f)return;let r=new FileReader();r.onload=async()=>{try{let x=JSON.parse(r.result),files=x._fileData||x._imageData||{};delete x._fileData;delete x._imageData;db=normalize(x);await clearFiles();for(let[id,d]of Object.entries(files))await putFile(id,d);persist();renderAll();alert('복원이 완료되었습니다.')}catch{alert('올바른 백업 파일이 아닙니다.')}};r.readAsText(f);e.target.value=''}function restoreAutoBackup(){try{let x=localStorage.getItem(AUTO_KEY);if(!x)return alert('자동 백업 슬롯이 비어 있습니다.');if(!confirm('자동 백업 슬롯의 상태로 복원하시겠습니까?'))return;db=normalize(JSON.parse(x));localStorage.setItem(KEY,JSON.stringify(db));renderAll();alert('자동 백업 슬롯을 복원했습니다.')}catch{alert('자동 백업 복원에 실패했습니다.')}}async function resetAll(){if(!confirm('모든 데이터를 삭제하시겠습니까?'))return;db=emptyDB();currentProjectId=null;localStorage.removeItem(AUTO_KEY);persist();await clearFiles();closeProject();renderAll()}
async function appSaveBlob(blob,name){if(window.Android){let r=new FileReader();r.onload=()=>Android.saveDataUrl(safeFileName(name),r.result);r.readAsDataURL(blob);return}let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=safeFileName(name);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),700)}
function appSaveDataUrl(data,name){if(window.Android){Android.saveDataUrl(safeFileName(name),data);return}let a=document.createElement('a');a.href=data;a.download=safeFileName(name);a.click()}
function appPrint(title,html){if(window.Android){Android.printHtml(title,`<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>body{font-family:system-ui,-apple-system,sans-serif;max-width:800px;margin:30px auto;padding:0 22px;line-height:1.7;color:#222}img{max-width:100%;max-height:500px;object-fit:contain;margin:14px 0}pre{white-space:pre-wrap;font-family:inherit}</style></head><body>${html}</body></html>`);return true}return false}
function handleNativeBack(){let m=document.getElementById('modal');if(m&&!m.classList.contains('hidden')){closeModal();return'handled'}let pv=document.getElementById('projectView');if(pv&&!pv.classList.contains('hidden')){closeProject();return'handled'}return'exit'}
function renderProjectAll(){renderSettings();renderCharacters();renderRelations();renderImages();renderSources();renderStories();renderTimeline();renderRecent()}function renderAll(){renderProjects();renderExportProjects();renderTrash();if(currentProjectId)renderProjectAll()}
setupSections();setMode(localStorage.getItem('creativeStudioMode')||'light');renderAll();
